function sensor(inv, slug) {
    return `sensor.voltronic_inv${inv}_${slug}`;
}
function select(inv, slug) {
    return `select.voltronic_inv${inv}_${slug}`;
}
function number(inv, slug) {
    return `number.voltronic_inv${inv}_${slug}`;
}
function switchEntity(inv, slug) {
    return `switch.voltronic_inv${inv}_${slug}`;
}
function text(inv, slug) {
    return `text.voltronic_inv${inv}_${slug}`;
}
function enabledInverters() {
    const list = Array.isArray(global.get("config.invertersList"))
        ? global.get("config.invertersList").map(Number).filter(n => [1, 2, 3].includes(n))
        : [];
    return list;
}

// -------------------------
// Helpers formatters ApexCharts
// -------------------------
function evalFixed(unit = "") {
    return `
EVAL:function(val) {
  val = Number(val || 0);
  if (!isFinite(val)) val = 0;
  return val.toFixed(2)${unit ? ` + " ${unit}"` : ""};
}`;
}

function evalLegend(unit = "") {
    return `
EVAL:function(seriesName, opts) {
  const val = Number((opts && opts.w && opts.w.globals && opts.w.globals.series && opts.w.globals.series[opts.seriesIndex]) || 0);
  return seriesName + ": " + val.toFixed(2)${unit ? ` + " ${unit}"` : ""};
}`;
}

function evalTotal(unit = "") {
    return `
EVAL:function(w) {
  const totals = Array.isArray(w?.globals?.seriesTotals) ? w.globals.seriesTotals : [];
  const total = totals.reduce((sum, v) => sum + Number(v || 0), 0);
  return total.toFixed(2)${unit ? ` + " ${unit}"` : ""};
}`;
}

// -------------------------
// Couleurs d'accent
// -------------------------
function accentColor(kind = "neutral") {
    const map = {
        neutral: "var(--primary-color)",
        blue: "#3b82f6",
        green: "#22c55e",
        orange: "#f59e0b",
        purple: "#a855f7",
        red: "#ef4444",
        cyan: "#06b6d4",
        gold: "#d4a017"
    };
    return map[kind] || map.neutral;
}

// -------------------------
// Styles
// -------------------------
function cardStyle(kind = "neutral", extra = "") {
    if (!HAS_CARD_MOD) return {};

    const accent = accentColor(kind);

    return {
        card_mod: {
            style: `
                ha-card {
                    background: var(--ha-card-background, var(--card-background-color));
                    color: var(--primary-text-color);
                    border-radius: 24px;
                    border: 1px solid var(--divider-color);
                    box-shadow:
                        0 6px 18px rgba(0,0,0,0.10),
                        0 1px 2px rgba(0,0,0,0.06);
                    overflow: hidden;
                    position: relative;
                    ${extra}
                }

                ha-card::before {
                    content: "";
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    height: 4px;
                    background: ${accent};
                    opacity: 0.95;
                    z-index: 1;
                }

                .card-header,
                .primary,
                .name,
                .value,
                .state {
                    color: var(--primary-text-color) !important;
                }

                .secondary,
                .secondary-text {
                    color: var(--secondary-text-color) !important;
                }
            `
        }
    };
}

function sectionBandStyle(kind = "neutral", extra = "") {
    if (!HAS_CARD_MOD) return {};

    const accent = accentColor(kind);

    return {
        card_mod: {
            style: `
                ha-card {
                    background: var(--ha-card-background, var(--card-background-color));
                    color: var(--primary-text-color);
                    border-radius: 22px;
                    border: 1px solid var(--divider-color);
                    box-shadow:
                        0 6px 16px rgba(0,0,0,0.08),
                        0 1px 2px rgba(0,0,0,0.05);
                    overflow: hidden;
                    position: relative;
                    ${extra}
                }

                ha-card::before {
                    content: "";
                    position: absolute;
                    top: 0;
                    left: 0;
                    bottom: 0;
                    width: 5px;
                    background: ${accent};
                    opacity: 0.95;
                    z-index: 1;
                }

                ha-card h1,
                ha-card h2,
                ha-card h3,
                ha-card strong {
                    color: var(--primary-text-color) !important;
                }

                ha-card p,
                ha-card li {
                    color: var(--secondary-text-color) !important;
                    opacity: 1 !important;
                }

                a {
                    color: ${accent} !important;
                }
            `
        }
    };
}

// -------------------------
// Helpers cartes
// -------------------------
function stack(cards) {
    return { type: "vertical-stack", cards: cards.filter(Boolean) };
}

function grid(columns, cards) {
    return { type: "grid", columns, square: false, cards: cards.filter(Boolean) };
}

function titleCard(title, subtitle = "", kind = "neutral") {
    return {
        type: "markdown",
        content: subtitle ? `# ${title}\n${subtitle}` : `# ${title}`,
        ...sectionBandStyle(kind, `
            ha-card {
                padding-left: 18px;
                padding-right: 18px;
            }
            ha-markdown {
                padding: 8px 4px 4px 4px !important;
            }
        `)
    };
}

function sectionTitle(title, subtitle = "", kind = "neutral") {
    return {
        type: "markdown",
        content: subtitle ? `## ${title}\n${subtitle}` : `## ${title}`,
        ...sectionBandStyle(kind, `
            ha-card {
                padding-left: 16px;
                padding-right: 16px;
            }
            ha-markdown {
                padding: 6px 4px 2px 4px !important;
            }
        `)
    };
}

function tile(entity, name, icon, kind = "neutral") {
    return {
        type: "tile",
        entity,
        name,
        icon,
        vertical: true,
        hide_state: false,
        features_position: "bottom",
        ...cardStyle(kind)
    };
}

function entitiesCard(title, entities, kind = "neutral") {
    return {
        type: "entities",
        title,
        show_header_toggle: false,
        state_color: true,
        entities: entities.filter(Boolean),
        ...cardStyle(kind, `
            .card-header {
                font-weight: 700 !important;
                padding-top: 16px !important;
            }
        `)
    };
}

function glanceCard(title, entities, columns = 4, kind = "neutral") {
    return {
        type: "glance",
        title,
        columns,
        show_state: true,
        show_name: true,
        state_color: true,
        entities: entities.filter(Boolean),
        ...cardStyle(kind, `
            .card-header {
                font-weight: 700 !important;
                padding-top: 16px !important;
            }
        `)
    };
}

function gaugeCard(entity, name, kind = "green", severity = null) {
    const base = {
        type: "gauge",
        entity,
        name,
        min: 0,
        max: 100,
        needle: true,
        ...cardStyle(kind)
    };

    if (severity) {
        base.severity = severity;
    }

    return base;
}

// =========================================================
// MINI GRAPH
// =========================================================
function miniGraph(title, entities, hours = 24, height = 260, kind = "neutral") {
    if (HAS_MINI_GRAPH) {
        return {
            type: "custom:mini-graph-card",
            name: title,
            hours_to_show: hours,
            points_per_hour: 2,
            hour24: true,
            animate: true,
            line_width: 3,
            font_size: 95,
            height,
            decimals: 2,
            show: {
                icon: false,
                name: true,
                state: true,
                legend: true,
                fill: true,
                labels: true,
                average: false,
                extrema: false
            },
            entities,
            ...cardStyle(kind)
        };
    }

    return {
        type: "history-graph",
        title,
        hours_to_show: hours,
        entities: entities.map(e => ({
            entity: typeof e === "string" ? e : e.entity,
            name: typeof e === "string" ? undefined : e.name
        })),
        ...cardStyle(kind)
    };
}

function statStrip(items) {
    return grid(
        items.length,
        items.map(i => tile(i.entity, i.name, i.icon, i.kind || "neutral"))
    );
}

