const fs = global.get("fs");
const path = global.get("path");

function firstWritableBase() {
    const candidates = [
        "/homeassistant/www/smart-modular-dashboard",
        "/config/www/smart-modular-dashboard"
    ];
    if (!fs) return candidates[0];
    for (const dir of candidates) {
        try {
            fs.mkdirSync(dir, { recursive: true });
            fs.accessSync(dir, fs.constants.W_OK);
            return dir;
        } catch (_) {}
    }
    return candidates[0];
}

