function getAddonConfig() {
    return global.get("addon_config") || {};
}

function walkAddonConfig(obj, visit, depth) {
    if (!obj || depth > 8) return;
    if (Array.isArray(obj)) {
        obj.forEach((value, index) => walkAddonConfig(value, (key, val) => visit(String(index), val), depth + 1));
        return;
    }
    if (typeof obj !== "object") return;
    Object.keys(obj).forEach(key => {
        const value = obj[key];
        visit(key, value);
        if (value && typeof value === "object") walkAddonConfig(value, visit, depth + 1);
    });
}

function configString(value) {
    if (value === undefined || value === null) return "";
    if (typeof value === "string") return value.toLowerCase().trim();
    if (typeof value === "boolean") return value ? "true" : "false";
    if (typeof value === "number") return String(value);
    return "";
}

function getDashboardLanguage() {
    const opts = getAddonConfig();
    return String(
        global.get("dashboard.language") ||
        global.get("config.dashboardLanguage") ||
        opts.dashboard_language ||
        "en"
    ).toLowerCase() === "fr" ? "fr" : "en";
}

function getBroadcastingMode() {
    const opts = getAddonConfig();
    const keys = [
        "broadcasting",
        "broadcast_mode",
        "mode_broadcasting",
        "bms_broadcasting",
        "jk_bms_broadcasting",
        "bms1_broadcasting",
        "bms_mode",
        "jk_bms_mode",
        "battery_mode",
        "battery_pack_mode",
        "bms_pack_mode",
        "pack_mode",
        "parallel_mode",
        "master_mode",
        "addon_mode",
        "mode"
    ];
    for (const key of keys) {
        const value = global.get("config." + key);
        if (value !== undefined && value !== null && value !== "") {
            if (value === true) return true;
            if (String(value).toLowerCase().includes("broadcast")) return true;
        }
        const optValue = opts[key];
        if (optValue !== undefined && optValue !== null && optValue !== "") {
            if (optValue === true) return true;
            if (String(optValue).toLowerCase().includes("broadcast")) return true;
        }
    }

    const globalKeys = [
        "broadcasting",
        "broadcast.mode",
        "broadcasting.mode",
        "bms.broadcasting",
        "bms.mode",
        "bms.master_mode",
        "bms.parallel_mode",
        "jk_bms.broadcasting",
        "jk_bms.mode",
        "jkbms.broadcasting",
        "jkbms.mode",
        "battery.broadcasting",
        "battery.mode",
        "battery.master_mode",
        "battery.parallel_mode",
        "battery_pack.mode",
        "battery_pack.broadcasting"
    ];
    for (const key of globalKeys) {
        const value = global.get(key);
        if (value !== undefined && value !== null && value !== "") {
            const v = configString(value);
            if (value === true || v.includes("broadcast") || v.includes("master")) return true;
        }
    }

    let found = false;
    walkAddonConfig(opts, (key, value) => {
        if (found) return;
        const k = String(key || "").toLowerCase();
        const v = configString(value);
        if ((k.includes("broadcast") || k.includes("parallel") || k.includes("master") || k.includes("bms") || k.includes("pack") || k.includes("mode")) && (value === true || v.includes("broadcast"))) {
            found = true;
        }
    }, 0);
    if (found) return true;
    return false;
}


function getBroadcastMasterIndex() {
    const opts = getAddonConfig();
    const keys = [
        "bms_master", "bms_master_index", "bms_master_id", "bms_master_number",
        "master_bms", "master_bms_index", "master_bms_id", "master_bms_number",
        "jk_bms_master", "jk_bms_master_index", "jkbms_master", "jkbms_master_index",
        "battery_master", "battery_master_index", "master_battery", "master_battery_index",
        "broadcast_master", "broadcast_master_index", "broadcasting_master", "broadcasting_master_index",
        "pack_master", "pack_master_index", "parallel_master", "parallel_master_index"
    ];
    function pick(value) {
        if (value === undefined || value === null || value === "") return 0;
        if (typeof value === "number" && isFinite(value) && value > 0) return Math.floor(value);
        if (typeof value === "boolean") return value ? 1 : 0;
        const txt = String(value).trim().toLowerCase();
        let m = txt.match(/bms\s*([1-9][0-9]*)/i) || txt.match(/master\D*([1-9][0-9]*)/i) || txt.match(/^([1-9][0-9]*)$/);
        return m ? parseInt(m[1], 10) : 0;
    }
    for (const key of keys) {
        const fromGlobal = pick(global.get("config." + key));
        if (fromGlobal) return fromGlobal;
        const fromOpt = pick(opts[key]);
        if (fromOpt) return fromOpt;
    }
    let found = 0;
    walkAddonConfig(opts, (key, value) => {
        if (found) return;
        const k = String(key || "").toLowerCase();
        if ((k.includes("master") && (k.includes("bms") || k.includes("battery") || k.includes("pack") || k.includes("jk"))) ||
            (k.includes("broadcast") && k.includes("master"))) {
            found = pick(value);
        }
    }, 0);
    return found || 1;
}

