th.floor(Math.random()*999999),type:'call_service',domain:'select',service:'select_option',service_data:{entity_id:entity,option}}))}\nfunction callNumber(entity,value){if(!WS||!entity||!Number.isFinite(value))return;WS.send(JSON.stringify({id:Math.floor(Math.random()*999999),type:'call_service',domain:'number',service:'set_value',service_data:{entity_id:entity,value}}))}\nfunction callSwitch(entity,turnOn){if(!WS||!entity)return;WS.send(JSON.stringify({id:Math.floor(Math.random()*999999),type:'call_service',domain:'switch',service:turnOn?'turn_on':'turn_off',service_data:{entity_id:entity}}))}\nfunction callText(entity,value){if(!WS||!entity)return;WS.send(JSON.stringify({id:Math.floor(Math.random()*999999),type:'call_service',domain:'text',service:'set_value',service_data:{entity_id:entity,value:String(value||'')}}))}\n\nfunction findAccessToken(obj, depth=0){\n  if(!obj || depth>8) return null;\n  if(typeof obj === 'string'){\n    const t=obj.trim();\n    if(t.length>40 && (t.split('.').length>=2 || t.startsWith('eyJ'))) return t;\n    return null;\n  }\n  if(typeof obj !== 'object') return null;\n  for(const k of ['access_token','accessToken','token','llat']){\n    if(typeof obj[k] === 'string' && obj[k].length>30) return obj[k];\n  }\n  for(const v of Object.values(obj)){\n    const found=findAccessToken(v, depth+1);\n    if(found) return found;\n  }\n  return null;\n}\nfunction getTokenOriginalHaStorage(){\n  try{\n    for(const k of Object.keys(localStorage||{})){\n      if(String(k).toLowerCase().includes('hasstokens')){\n        try{\n          const raw=JSON.parse(localStorage.getItem(k));\n          if(raw?.access_token) return raw.access_token;\n          if(raw?.data){\n            const first=Object.values(raw.data)[0];\n            if(first?.access_token) return first.access_token;\n            const found=findAccessToken(first); if(found) return found;\n          }\n          const found=findAccessToken(raw); if(found) return found;\n        }catch(e){}\n      }\n    }\n  }catch(e){}\n  return null;\n}\nfunction getTokenFromStorageArea(store){\n  try{\n    if(!store) return null;\n    const manual=store.getItem('smart_voltronic_ha_token') || store.getItem('sv_ha_token');\n    if(manual && manual.length>30) return manual.trim();\n    const keys=[];\n    for(let i=0;i<store.length;i++) keys.push(store.key(i));\n    keys.sort((a,b)=>{\n      const aa=String(a).toLowerCase(), bb=String(b).toLowerCase();\n      return (bb.includes('hass')||bb.includes('token'))-(aa.includes('hass')||aa.includes('token'));\n    });\n    for(const k of keys){\n      try{\n        const val=store.getItem(k);\n        if(!val) continue;\n        const lk=String(k).toLowerCase();\n        if(lk.includes('hass') || lk.includes('token') || String(val).includes('access_token') || String(val).includes('accessToken')){\n          let raw=val;\n          try{ raw=JSON.parse(val); }catch(e){}\n          const found=findAccessToken(raw);\n          if(found) return found;\n        }\n      }catch(e){}\n    }\n  }catch(e){}\n  return null;\n}\nasync function getTokenFromHassConnection(){\n  const candidates=[];\n  try{candidates.push(window.hassConnection)}catch(e){}\n  try{if(window.parent && window.parent!==window) candidates.push(window.parent.hassConnection)}catch(e){}\n  try{candidates.push(window.hass?.connection)}catch(e){}\n  try{if(window.parent && window.parent!==window) candidates.push(window.parent.hass?.connection)}catch(e){}\n  for(const c of candidates){\n    try{\n      const resolved=(c && typeof c.then==='function') ? await c : c;\n      if(!resolved) continue;\n      const found=findAccessToken(resolved); if(found) return found;\n      const auth=resolved?.conn?.options?.auth || resolved?.options?.auth || resolved?.auth;\n      if(auth){\n        if(typeof auth.accessToken==='string') return auth.accessToken;\n        if(typeof auth.accessToken==='function'){\n          const t=await auth.accessToken(); if(t) return t;\n        }\n        const foundAuth=findAccessToken(auth); if(foundAuth) return foundAuth;\n      }\n    }catch(e){}\n  }\n  return null;\n}\nfunction tokenFromUrl(){\n  try{\n    const u=new URL(location.href);\n    const q=u.searchParams.get('token') || u.searchParams.get('ha_token');\n    if(q && q.length>30) return q.trim();\n    const m=String(location.hash||'').match(/(?:token|ha_token)=([^&]+)/i);\n    if(m) return decodeURIComponent(m[1]).trim();\n  }catch(e){}\n  return null;\n}\nasync function getToken(){\n  const t = tokenFromUrl()\n    || getTokenOriginalHaStorage()\n    || getTokenFromStorageArea(window.localStorage)\n    || getTokenFromStorageArea(window.sessionStorage)\n    || (()=>{try{return getTokenFromStorageArea(window.parent?.localStorage)}catch(e){return null}})()\n    || (()=>{try{return getTokenFromStorageArea(window.parent?.sessionStorage)}catch(e){return null}})()\n    || await getTokenFromHassConnection();\n  if(t){\n    try{ localStorage.setItem('smart_voltronic_ha_token', t); }catch(e){}\n  }\n  return t;\n}\nfunction removeHaTokenNotice(){\n  const old=document.getElementById('ha_token_notice'); if(old) old.remove();\n}\nfunction showHaTokenNotice(){\n  removeHaTokenNotice();\n}\nfunction websocketUrl(){\n  const proto=location.protocol==='https:'?'wss://':'ws://';\n  return proto+location.host+'/api/websocket';\n}\nfunction connectWebsocket(token){\n  try{ if(WS && WS.readyState===WebSocket.OPEN) WS.close(); }catch(e){}\n  WS=new WebSocket(websocketUrl());\n  WS.onmessage=ev=>{\n    let msg; try{msg=JSON.parse(ev.data)}catch(e){return}\n    if(msg.type==='auth_required') WS.send(JSON.stringify({type:'auth',access_token:token}));\n    if(msg.type==='auth_ok'){\n      removeHaTokenNotice();\n      WS.send(JSON.stringify({id:1,type:'get_states'}));\n      WS.send(JSON.stringify({id:2,type:'subscribe_events',event_type:'state_changed'}));\n    }\n    if(msg.type==='auth_invalid'){\n      console.warn('Authentification HA invalide');\n      showHaTokenNotice();\n    }\n    if(msg.id===1 && msg.type==='result' && Array.isArray(msg.result)){\n      msg.result.forEach(e=>STATES[e.entity_id]=e);\n      scheduleUpdate();\n    }\n    if(msg.id===2 && msg.type==='event'){\n      const e=msg.event?.data?.new_state;\n      if(e){STATES[e.entity_id]=e;scheduleUpdate()}\n    }\n  };\n  WS.onerror=()=>{console.warn('Erreur websocket HA'); showHaTokenNotice();};\n  WS.onclose=()=>{setTimeout(async()=>{const t=await getToken(); if(t) connectWebsocket(t);},4000)};\n}\nlet STARTING=false;\nasync function start(){\n  if(STARTING) return;\n  STARTING=true;\n  try{\n    setInterval(()=>set('clock',new Date().toLocaleTimeString()),1000);\n    try{renderInverters()}catch(e){console.error(e)}\n    try{updateEcoCharts()}catch(e){console.error(e)}\n    const token=await getToken();\n    HA_TOKEN=token;\n    if(!token){\n      console.warn('Token HA introuvable. Affichage du panneau de connexion manuelle.');\n      showHaTokenNotice();\n      try{update()}catch(e){console.error(e)}\n      return;\n    }\n    connectWebsocket(token);\n  } finally {\n    setTimeout(()=>{STARTING=false},500);\n  }\n}\n\n\n/* ===== V24 SAFE PATCH: keep v21 websocket/update, only visual + extra data ===== */\nfunction v24EntityVal(id,def='--'){\n  const st=STATES[id];\n  if(!st || bad(st.state)) return def;\n  return st.state;\n}\nfunction v24Num(ids){return num(Array.isArray(ids)?ids:[ids])}\nfunction v24First(ids,def='--'){return state(Array.isArray(ids)?ids:[ids],def)}\nfunction v24AlarmStatus(v){\n  const s=String(v??'').trim(); const l=s.toLowerCase();\n  if(!s || ['unknown','unavailable','none','off','ok','normal','clear','0','false','--'].includes(l)) return {txt:s && !['unknown','unavailable'].includes(l)?s:'OK', cls:'alarm-ok', icon:'✅'};\n  if(['on','true','active','fault','warning','warn','alarm'].includes(l) || l.includes('fault') || l.includes('warn') || l.includes('alarm')) return {txt:s, cls:l.includes('warn')?'alarm-warn':'alarm-fault', ic