empChip=$('core_temp_chip');\n  const screen=document.querySelector('.inverter-core .screen');\n  if(screen && !tempChip){\n    const chips=screen.querySelector('.core-metrics');\n    if(chips) chips.insertAdjacentHTML('beforeend','<span id=\"core_temp_chip\" class=\"core-chip\">🌡️ <b id=\"core_temp\">--</b>°C</span>');\n  }\n  if($('core_temp')) set('core_temp',invTemp?invTemp.toFixed(1):'--');\n  document.querySelectorAll('.core-alarm-strip').forEach(e=>e.remove());\n  const bat=document.querySelector('.n-bat');\n  if(bat){\n    const socTxt=state(E.soc,'--');\n    bat.innerHTML=`<div class=\"ico\">🔋</div><div class=\"label\">Battery</div><div class=\"value\"><span id=\"soc\">${bad(socTxt)?'--':Math.round(n(socTxt))}</span>%</div><div class=\"bat-metrics\"><div class=\"bat-chip\"><small>Power</small><b>${Number.isFinite(battPower)?Math.round(battPower):'--'} W</b></div><div class=\"bat-chip\"><small>Tension</small><b>${battV?battV.toFixed(2):'--'} V</b></div><div class=\"bat-chip\"><small>Courant</small><b>${battA?battA.toFixed(1):'--'} A</b></div></div><div class=\"small temp-bms-line\">🌡️ Temp. JK moyenne : <b>${bmsTemp?bmsTemp.toFixed(1):'--'} °C</b></div><div class=\"small\">Jour +<span id=\"bat_charge_day\">${globalNum(E.chargeDay,()=>sumInv('battery_charge_day_kwh')).toFixed(2)}</span> kWh · -<span id=\"bat_dis_day\">${globalNum(E.dischargeDay,()=>sumInv('battery_discharge_day_kwh')).toFixed(2)}</span> kWh</div>`;\n  }\n  v27UpdateInvAlarmCards();\n  const bmsAlarm=v27GetBmsGlobalAlarm();\n  const bmsSt=v24AlarmStatus((bmsAlarm.active||'')+' '+(bmsAlarm.details||''));\n  const bmsBeaconBox=$('v24_bms_beacon_box');\n  if(bmsBeaconBox){\n    bmsBeaconBox.style.display=bmsSt.cls==='alarm-ok'?'none':'flex';\n    bmsBeaconBox.classList.remove('has-ok','has-warn','has-fault');\n    bmsBeaconBox.classList.add(bmsSt.cls==='alarm-fault'?'has-fault':bmsSt.cls==='alarm-warn'?'has-warn':'has-ok');\n    const siren=$('v24_bms_beacon');\n    if(siren) siren.title=bmsSt.txt||'BMS alarm';\n  }\n  const d=$('donut_mix');\n  if(d){\n    const solar=parseFloat(($('solar_pct_big')?.textContent||'0').replace('%',''))||0;\n    const batp=parseFloat(($('bat_pct_big')?.textContent||'0').replace('%',''))||0;\n    const gridp=Math.max(0,100-solar-batp);\n    d.style.background=`conic-gradient(var(--solar) 0 ${solar}%, var(--bat) ${solar}% ${solar+batp}%, var(--grid) ${solar+batp}% ${solar+batp+gridp}%, #1e293b ${solar+batp+gridp}% 100%)`;\n  }\n}\nfunction invLiveCardV24(i){\n return `<div class=\"inv-hero\">${card('☀️ PV',`<span id=\"inv_d_${i}_pv\">--</span>`,'W','solar')}${card('🏠 Load',`<span id=\"inv_d_${i}_load\">--</span>`,'W','load')}${card('⚡ Réseau',`<span id=\"inv_d_${i}_grid\">--</span>`,'W','gridc')}${card('🔋 SOC',`<span id=\"inv_d_${i}_soc\">--</span>`,'%','bat')}${card('🔌 Tension sortie',`<span id=\"inv_d_${i}_outv\">--</span>`,'V','')}${card('〰️ Frequency',`<span id=\"inv_d_${i}_hz\">--</span>`,'Hz','')}${card('📈 Output current',`<span id=\"inv_d_${i}_outa\">--</span>`,'A','')}${card('🌡️ Température',`<span id=\"inv_d_${i}_temp\">--</span>`,'°C','orange')}${card('🔆 MPPT 1',`<span id=\"inv_d_${i}_mppt1\">--</span>`,'W','solar')}${card('🔆 MPPT 2',`<span id=\"inv_d_${i}_mppt2\">--</span>`,'W','solar')}${card('🔋 Batt. V',`<span id=\"inv_d_${i}_batv\">--</span>`,'V','bat')}${card('🔋 Batt. P',`<span id=\"inv_d_${i}_batp\">--</span>`,'W','bat')}</div>`;\n}\nfunction showInvView(id,btn){window.__activeInvView=id;document.querySelectorAll('#inverters .inv-view').forEach(v=>v.classList.remove('active')); const e=$(id); if(e)e.classList.add('active'); document.querySelectorAll('#inverters .inv-subnav .subtab').forEach(b=>b.classList.remove('active')); if(btn)btn.classList.add('active')}\nfunction showInvInner(i,which,btn){window.__activeInvInner=window.__activeInvInner||{};window.__activeInvInner[i]=which;document.querySelectorAll(`#inv_${i}_detail .inv-inner-view`).forEach(v=>v.classList.remove('active')); const e=$(`inv_${i}_${which}`); 