\">--</span>','A','')}${card('🌡️ Average temperature','<span id=\"inv_g_temp\">--</span>','°C','orange')}</div><div class=\"cards2 inv-detected-cards\">${ids.map(i=>`<div class=\"card inv-detected\"><div class=\"label\">⚡ Inverter ${i}</div><div class=\"value\"><span id=\"inv_${i}_mini_pv\">--</span></div><div class=\"mini-grid\"><span>Load <b id=\"inv_${i}_mini_load\">--</b></span><span>SOC <b id=\"inv_${i}_mini_soc\">--</b></span><span>Temp <b id=\"inv_${i}_mini_temp\">--</b></span></div></div>`).join('')}</div>`;\n}\nfunction renderInverters(force=false){\n const box=$('inverter_wall'); if(!box)return; const ids=getInverterIds(); const sig=ids.join(',');\n if(!force && box.dataset.sig===sig && box.dataset.built==='1') return;\n const active=window.__activeInvView||'inv_global_view'; const inner=window.__activeInvInner||{};\n box.dataset.sig=sig; box.dataset.built='1';\n box.innerHTML=`<div class=\"inv-subnav\"><button class=\"subtab ${active==='inv_global_view'?'active':''}\" onclick=\"showInvView('inv_global_view',this)\">🌐 Global</button>${ids.map(i=>`<button class=\"subtab ${active===`inv_${i}_detail`?'active':''}\" onclick=\"showInvView('inv_${i}_detail',this)\">Inverter ${i}</button>`).join('')}</div><div id=\"inv_global_view\" class=\"inv-view ${active==='inv_global_view'?'active':''}\">${v27GlobalInverterCards(ids)}</div>${ids.map(i=>{const a=inner[i]||'live';return `<div id=\"inv_${i}_detail\" class=\"inv-view ${active===`inv_${i}_detail`?'active':''}\"><div class=\"inv-innernav\"><button class=\"subtab ${a==='live'?'active':''}\" onclick=\"showInvInner(${i},'live',this)\">⚡ Live</button><button class=\"subtab ${a==='cmd'?'active':''}\" onclick=\"showInvInner(${i},'cmd',this)\">🔧 Commandes</button><button class=\"subtab ${a==='diag'?'active':''}\" onclick=\"showInvInner(${i},'diag',this)\">🩺 Diagnostic</button></div><div id=\"inv_${i}_live\" class=\"inv-inner-view ${a==='live'?'active':''}\">${invLiveCardV24(i)}</div><div id=\"inv_${i}_cmd\" class=\"inv-inner-view inv-command-diag ${a==='cmd'?'active':''}\">${invParamsV24(i)}</div><div id=\"inv_${i}_diag\" class=\"inv-inner-view inv-command-diag ${a==='diag'?'active':''}\">${invDiagV24(i)}</div></div>`}).join('')}`;\n}\nfunction v27UpdateInverterValues(){\n const pv=globalNum(E.pv,()=>sumInv('pv_total_power')), load=globalNum(E.load,()=>sumInv('ac_output_active_power')), grid=globalNum(E.grid,()=>sumInv('grid_power'));\n const batt=v24Num(['sensor.voltronic_global_battery_power']), outA=v24Num(['sensor.voltronic_global_inverter_output_current']);\n const outV=v24Num(['sensor.voltronic_global_ac_output_voltage','sensor.voltronic_global_output_voltage'])||avgInv('ac_output_voltage',['output_voltage']);\n const hz=v24Num(['sensor.voltronic_global_ac_output_frequency','sensor.voltronic_global_output_frequency'])||avgInv('ac_output_frequency',['output_frequency']);\n for(const [id,val] of [['inv_g_pv',Math.round(pv)],['inv_g_load',Math.round(load)],['inv_g_grid',Math.round(grid)],['inv_g_bat',Math.round(batt)],['inv_g_out_v',outV?outV.toFixed(1):'--'],['inv_g_out_hz',hz?hz.toFixed(2):'--'],['inv_g_out_a',outA?outA.toFixed(1):'--'],['inv_g_temp',v27TempInvAvg()?v27TempInvAvg().toFixed(1):'--']]){const e=$(id); if(e)e.textContent=val;}\n for(const i of getInverterIds()){\n   const pvI=invNum(i,'pv_total_power'), loadI=invNum(i,'ac_output_active_power'), gridI=invNum(i,'grid_power'), socI=invNum(i,'battery_capacity',['battery_soc']);\n   const outVI=invNum(i,'ac_output_voltage',['output_voltage']), hzI=invNum(i,'ac_output_frequency',['output_frequency']), outAI=invNum(i,'ac_output_current',['output_current']);\n   const tempI=v27TempInvWide(i), mppt1=invNum(i,'pv1_power'), mppt2=invNum(i,'pv2_power'), batV=invNum(i,'battery_voltage'), batP=invNum(i,'battery_power');\n   const values={}; values[`inv_${i}_mini_pv`]=Math.round(pvI)+' W'; values[`inv_${i}_mini_load`]=Math.round(loadI)+' W'; values[`inv_${i}_mini_soc`]=Math.round(socI)+'%'; values[`inv_${i}_mini_temp`]=(tempI||0).toFixed(1)+'°C';\n   values[`inv_d_${i}_pv`]=Math.round(pvI); values[`inv_d_${i}_load`]=Math.round(loadI); values[`inv_d_${i}_grid`]=Math.round(gridI); values[`inv_d_${i}_soc`]=Math.round(socI); values[`inv_d_${i}_outv`]=(outVI||0).toFixed(1); values[`inv_d_${i}_hz`]=(hzI||0).toFixed(2); values[`inv_d_${i}_outa`]=(outAI||0).toFixed(1); values[`inv_d_${i}_temp`]=(tempI||0).toFixed(1); values[`inv_d_${i}_mppt1`]=Math.round(mppt1); values[`inv_d_${i}_mppt2`]=Math.round(mppt2); values[`inv_d_${i}_batv`]=(batV||0).toFixed(2); values[`inv_d_${i}_batp`]=Math.round(batP);\n   for(const [id,val] of Object.entries(values)){const e=$(id); if(e)e.textContent=val;}\n }\n}\n\n/* ===== V28 targeted fixes ===== */\nfunction v28Words(slug){return String(slug||'').toLowerCase().split('_').filter(w=>w && !['param','diag','pct'].includes(w));}\nfunction v28FindEntity(type,i,slug,extra=[]){\n  const base=`${type}.voltronic_inv${i}`;\n  const exact=[`${base}_param_${slug}`,`${base}_${slug}`,`${type}.voltronic_inverter_${i}_param_${slug}`,`${type}.voltronic_inverter_${i}_${slug}`,...extra];\n  for(const id of exact){ if(STATES[id]) return id; }\n  const words=v28Words(slug);\n  const all=Object.keys(STATES||{});\n  const hit=all.find(id=>id.startsWith(type+'.') && id.toLowerCase().includes(`voltronic_inv${i}`) && words.every(w=>id.toLowerCase().includes(w)));\n  return hit || exact[0];\n}\nparamEntity=function(i,type,slug){return v28FindEntity(type,i,slug);};\ndiagEntity=function(i,type,slug){\n  if(type==='switch') return v28FindEntity('switch',i,slug,[`switch.voltronic_inv${i}_${slug}`]);\n  if(type==='text') return v28FindEntity('text',i,slug,[`text.voltronic_inv${i}_${slug}`]);\n  return v28FindEntity('sensor',i,slug,[sensor(i,slug)]);\n};\nfunction v28ExistsEntity(ent,type){return !!STATES[ent] || type==='text';}\ninvParamsV24=function(i){\n  return `<div class=\"param-pack\"><div class=\"param-title\">🔧 Commandes onduleur ${i}</div>${PARAM_DEFS.map(([type,slug,name])=>{const ent=paramEntity(i,type,slug); const exists=!!STATES[ent]; return `<div class=\"param-row ${exists?'':'param-missing'}\"><div><div class=\"param-name\">${name}</div><div class=\"param-entity\">${ent}${exists?'':' · non trouvé'}</div></div><div class=\"param-control\">${exists?paramControl(ent,type):'<span class=\"small\">Entité absente</span>'}</div></div>`}).join('')}</div>`;\n};\ninvDiagV24=function(i){\n  return `<div class=\"diag-pack\"><div class=\"diag-title\"><span>🩺 Diagnostic onduleur ${i}</span><span class=\"diag-status-pill\">Live</span></div><div class=\"diag-grid\">${DIAG_DEFS.map(([type,slug,name])=>{const ent=diagEntity(i,type,slug); const exists=v28ExistsEntity(ent,type); const val=diagValue(ent); const big=['diag_raw_command','diag_raw_response','diag_fault_details','diag_warn_details','battery_health_reason'].includes(slug); return `<div class=\"diag-card ${big?'big':''} ${diagCardClass(slug,val)} ${exists?'':'param-missing'}\"><div class=\"label\">${name}</div><div class=\"value\">${exists?escAttr(val):'--'}</div><div class=\"small\">${ent}${exists?'':' · non trouvé'}</div>${exists?diagControl(ent,type,val):''}</div>`}).join('')}</div></div>`;\n};\nv27TempInvWide=function(i){\n  const slugs=['inverter_heat_sink_temp','max_internal_temperature','q1_internal_temperature','q1_inverter_temperature','q1_boost_temperature','inverter_temperature','internal_temperature','diag_temperature','temperature','heat_sink_temperature','radiator_temperature'];\n  for(const slug of slugs){const v=invNum(i,slug); if(Number.isFinite(v)&&v!==0) return v;}\n  const prefix=`sensor.voltronic_inv${i}`;\n  for(const [id,st] of Object.entries(STATES||{})){\n    const low=id.toLowerCase();\n    if(id.startsWith(prefix) && (low.includes('temp')||low.includes('temperature')||low.includes('heat'))){\n      const v=parseFloat(st?.state); if(Number.isFinite(v)&&v!==0) return v;\n    }\n  }\n  return 0;\n};\nfunction v28RenderCoreTemp(){\n  const extra=document.querySelector('.inverter-c