.nav{display:grid;gap:8px}.tab{border:1px solid rgba(126,161,206,.22);background:rgba(15,25,45,.72);color:#cbd5e1;padding:12px;border-radius:14px;text-align:left;font-weight:1000;cursor:pointer;font-size:15px}.tab.active{background:linear-gradient(135deg,rgba(46,199,255,.25),rgba(46,199,255,.09));border-color:rgba(46,199,255,.7);color:#fff}.tab.sub{margin-left:18px;padding:10px 12px;font-size:14px;background:rgba(15,25,45,.48)}.tab.missing{display:none}
.main{min-width:0;display:grid;grid-template-rows:58px 1fr;height:100vh}.topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 18px;border-bottom:1px solid rgba(126,161,206,.14);background:rgba(5,11,22,.60)}
.title{display:flex;align-items:center;gap:10px}.title h1{margin:0;font-size:27px;letter-spacing:-1.1px}.badge{padding:8px 13px;border-radius:999px;background:rgba(255,159,67,.16);border:1px solid rgba(255,159,67,.48);color:#ffd7a6;font-weight:1000;font-size:12px}.ok{color:#baffcf;border-color:rgba(36,224,109,.35);background:rgba(36,224,109,.13)}
.framewrap{position:relative;min-width:0;min-height:0}iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:#050b16}.empty{position:absolute;inset:0;display:none;align-items:center;justify-content:center;text-align:center;padding:25px;color:var(--muted)}
@media(max-width:760px){.app{grid-template-columns:1fr;grid-template-rows:auto 1fr}.sidebar{border-right:0;border-bottom:1px solid rgba(126,161,206,.22);display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px;padding:4px 6px}.brand{font-size:15px;padding:1px 3px;margin:0}.brand .bolt{font-size:22px}.premium{align-self:center;margin:0;padding:5px 7px;font-size:9px;line-height:1.1;border-radius:11px}.nav{grid-column:1/-1;display:flex;gap:5px;overflow-x:auto;padding-bottom:0}.tab{flex:0 0 auto;padding:7px 9px;font-size:12px;border-radius:11px;white-space:nowrap}.tab.sub{margin-left:0}.main{height:auto;min-height:0}.topbar{height:auto;flex-wrap:nowrap;padding:4px 8px;gap:7px}.title{min-width:0}.title h1{font-size:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.badge{padding:5px 8px;font-size:10px;white-space:nowrap}.framewrap{height:calc(100vh - 108px)}}
</style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><span class="bolt">⚡</span><span>Smart<br>Energy</span></div>
    <div class="premium">${shellText.premiumActive}<br><span id="module_count">--</span> ${shellText.modulesAvailable}</div>
    <div class="nav" id="module_nav">
      <button class="tab" data-module="voltronic" data-view="global" data-label="${shellText.globalFlow}" data-title="${shellText.smartVoltronic}" data-url="/local/smart-modular-dashboard/voltronic.html">⚡ ${shellText.globalFlow}</button>
      <button class="tab sub" data-module="voltronic" data-view="inverters" data-label="${shellText.inverters}" data-title="${shellText.smartVoltronic}" data-url="/local/smart-modular-dashboard/voltronic.html">🧩 ${shellText.inverters}</button>
      <button class="tab sub" data-module="voltronic" data-view="energy" data-label="${shellText.energy}" data-title="${shellText.smartVoltronic}" data-url="/local/smart-modular-dashboard/voltronic.html">📊 ${shellText.energy}</button>
      <button class="tab" data-module="jkbms" data-label="${bmsMainLabel}" data-title="${bmsMainLabel}" data-url="/local/smart-modular-dashboard/jkbms.html">🔋 ${bmsMainLabel}</button>
      <button class="tab" data-module="finance" data-label="Finance" data-title="${shellText.smartFinance}" data-url="/local/smart-modular-dashboard/finance.html">💶 Finance</button>
    </div>
  </aside>
  <main class="main">
    <div class="topbar">
      <div class="title"><h1 id="page_title">Smart Energy Premium</h1><span class="badge">PREMIUM</span><span class="badge ok">● ${shellText.systemOk}</span></div>
      <button class="badge" onclick="location.reload()">↻ ${shellText.refresh}</button>
    </div>
    <div class="framewrap">
      <iframe id="module_frame" src="about:blank"></iframe>
      <div id="empty" class="empty"><div><h2>${shellText.noModuleTitle}</h2><p>${shellText.noModuleBody}</p></div></div>
    </div>
  </main>
</div>
<script>
(function(){
  const frame=document.getElementById('module_frame');
  const empty=document.getElementById('empty');
  const title=document.getElementById('page_title');
  const count=document.getElementById('module_count');
  const buttons=[...document.querySelectorAll('.tab')];
  let currentUrl='';

  const SMART_ENERGY_BUILD_VERSION='v72.0-fr-en-bms-master';
  const SV_DASHBOARD_LANG='${dashboardLanguage}';
  const SV_BROADCASTING_MODE=${isBroadcastingMode ? "true" : "false"};
  const SV_BMS_MASTER_INDEX=${broadcastMasterIndex};
  try{window.__SMART_ENERGY_BUILD_VERSION=SMART_ENERGY_BUILD_VERSION;}catch(e){}
  let SHELL_HA_TOKEN='';
  let shellHistorySeq=1;
  function shellFindAccessToken(obj, depth){
    depth=depth||0;
    if(!obj || depth>8) return null;
    if(typeof obj==='string'){
      var t=obj.trim();
      if(t.length>40 && (t.split('.').length>=2 || t.indexOf('eyJ')===0)) return t;
      return null;
    }
    if(typeof obj!=='object') return null;
    var keys=['access_token','accessToken','token','llat'];
    for(var i=0;i<keys.length;i++){try{if(typeof obj[keys[i]]==='string' && obj[keys[i]].length>30) return obj[keys[i]];}catch(e){}}
    try{var vals=Object.values(obj); for(var j=0;j<vals.length;j++){var f=shellFindAccessToken(vals[j],depth+1); if(f)return f;}}catch(e){}
    return null;
  }
  function shellTokenFromStore(store){
    try{
      if(!store) return null;
      var manual=store.getItem('smart_voltronic_ha_token')||store.getItem('sv_ha_token');
      if(manual&&manual.length>30)return manual.trim();
      var keys=[]; for(var i=0;i<store.length;i++) keys.push(store.key(i));
      keys.sort(function(a,b){a=String(a).toLowerCase();b=String(b).toLowerCase();return ((b.indexOf('hass')>=0||b.indexOf('token')>=0)?1:0)-((a.indexOf('hass')>=0||a.indexOf('token')>=0)?1:0);});
      for(var k=0;k<keys.length;k++){
        var key=keys[k], val=store.getItem(key); if(!val)continue;
        var lk=String(key).toLowerCase();
        if(lk.indexOf('hass')>=0||lk.indexOf('token')>=0||String(val).indexOf('access_token')>=0||String(val).indexOf('accessToken')>=0){
          var raw=val; try{raw=JSON.parse(val);}catch(e){}
          var found=shellFindAccessToken(raw,0); if(found)return found;
        }
      }
    }catch(e){}
    return null;
  }
  function shellScanDocForHass(doc, depth, out){
    if(!doc || depth>5) return;
    function add(x){try{if(x&&out.indexOf(x)<0)out.push(x)}catch(e){}}
    try{add(doc.hass)}catch(e){}
    ['home-assistant','home-assistant-main','ha-panel-lovelace','hui-root','partial-panel-resolver','home-assistant-router'].forEach(function(sel){
      try{var el=doc.querySelector&&doc.querySelector(sel); if(el){add(el.hass); if(el.shadowRoot)shellScanDocForHass(el.shadowRoot,depth+1,out);}}catch(e){}
    });
    try{Array.prototype.slice.call(doc.querySelectorAll('*')).slice(0,220).forEach(function(el){try{add(el.hass); if(el.shadowRoot)shellScanDocForHass(el.shadowRoot,depth+1,out)}catch(e){}})}catch(e){}
  }
  function shellGetParentHassObject(){
    var tries=[];function add(x){try{if(x&&tries.indexOf(x)<0)tries.push(x)}catch(e){}}
    try{add(window.hass)}catch(e){}
    try{add(window.parent&&window.parent.hass)}catch(e){}
    try{add(window.top&&window.top.hass)}catch(e){}
    try{shellScanDocForHass(document,0,tries)}catch(e){}
    try{if(window.parent&&window.parent!==window)shellScanDocForHass(window.parent.document,0,tries)}catch(e){}
    try{if(window.top&&window.top!==window)shellScanDocForHass(window.top.document,0,tries)}catch(e){}
    return tries.find(function(h){return h&&typeof h.callApi==='function'}) || null;
  }
  async function shellTokenFromHass(){
    var candidates=[];
    try{candidates.push(window.hassConnection)}catch(e){}
    try{candidates.push(window.hass&&window.hass.connection)}catch(e){}
    try{var h=shellGetParentHassObject(); if(h)candidates.push(h.connection||h)}catch(e){}
    for(var i=0;i<candidates.length;i++){
      try{
        var c=candidates[i]; var resolved=(c&&typeof c.then==='function')?await c:c; if(!resolved)continue;
        var found=shellFindAccessToken(resolved,0); if(found)return found;
        var auth=(resolved.conn&&resolved.conn.options&&resolved.conn.options.auth)||(resolved.options&&resolved.options.auth)||resolved.auth;
        if(auth){
          if(typeof auth.accessToken==='string')return auth.accessToken;
          if(typeof auth.accessToken==='function'){var t=await auth.accessToken(); if(t)return t;}
          var fa=shellFindAccessToken(auth,0); if(fa)return fa;
        }
      }catch(e){}
    }
    return null;
  }
  async function shellGetToken(){
    if(SHELL_HA_TOKEN&&SHELL_HA_TOKEN.length>30)return SHELL_HA_TOKEN;
    var t=shellTokenFromStore(window.localStorage)||shellTokenFromStore(window.sessionStorage);
    if(!t){try{t=shellTokenFromStore(window.parent&&window.parent.localStorage)||shellTokenFromStore(window.parent&&window.parent.sessionStorage)}catch(e){}}
    if(!t){try{t=shellTokenFromStore(window.top&&window.top.localStorage)||shellTokenFromStore(window.top&&window.top.sessionStorage)}catch(e){}}
    if(!t)t=await shellTokenFromHass();
    if(t){SHELL_HA_TOKEN=t;try{localStorage.setItem('smart_voltronic_ha_token',t)}catch(e){}}
    return t;
  }
  async function sendTokenToFrame(){
    var t=await shellGetToken();
    if(!t||!frame||!frame.contentWindow)return;
    try{frame.contentWindow.postMessage({type:'smart-energy-ha-token',token:t},'*')}catch(e){}
    try{frame.contentWindow.HA_TOKEN=t;frame.contentWindow.__SV_HA_TOKEN=t;frame.contentWindow.localStorage.setItem('smart_voltronic_ha_token',t)}catch(e){}
  }
  function shellHistoryNumber(v){var m=String(v==null?'':v).replace(',','.').match(/-?\d+(?:\.\d+)?/);var x=m?parseFloat(m[0]):NaN;return Number.isFinite(x)?x:NaN;}
  function shellLooksTime(v){if(typeof v==='number')return Number.isFinite(v)&&v>1000000000;var s=String(v==null?'':v).trim();if(!s)return false;if(/^-?\\d+(?:\\.\\d+)?$/.test(s))return Number(s)>1000000000;var ms=new Date(s).getTime();return Number.isFinite(ms);}
  function shellHistoryTime(row){var raw;if(Array.isArray(row)){if(shellLooksTime(row[0]))raw=row[0];else if(shellLooksTime(row[1]))raw=row[1];else raw=row[0];}else raw=row&&(row.last_changed||row.last_updated||row.lu||row.lc||row.t||row.time||row.datetime||row.timestamp||row.ts||row.last_changed_ts||row.last_updated_ts);if(typeof raw==='number')return raw<20000000000?raw*1000:raw;var ms=new Date(raw).getTime();return Number.isFinite(ms)?ms:NaN;}
  function shellHistoryState(row){if(Array.isArray(row)){if(shellLooksTime(row[0]))return row[1];if(shellLooksTime(row[1]))return row[0];return row[1];}return row&&(row.state!==undefined?row.state:(row.s!==undefined?row.s:(row.value!==undefined?row.value:(row.v!==undefined?row.v:row.y))));}
  function shellRowLike(x){if(Array.isArray(x))return x.length>=2&&(shellLooksTime(x[0])||shellLooksTime(x[1]));return x&&typeof x==='object'&&(x.state!==undefined||x.s!==undefined||x.value!==undefined||x.v!==undefined||x.y!==undefined)&&(x.last_changed||x.last_updated||x.lu||x.lc||x.t||x.time||x.datetime||x.timestamp||x.ts||x.last_changed_ts||x.last_updated_ts);}
  function shellParseHistoryRows(json,id){
    id=String(id||'').trim();var rows=[],seen=[];
    function walk(x,depth){if(!x||depth>10)return;if(shellRowLike(x)){rows.push(x);return;}if(Array.isArray(x)){for(var i=0;i<x.length;i++)walk(x[i],depth+1);return;}if(typeof x==='object'){if(seen.indexOf(x)>=0)return;seen.push(x);if(x[id])walk(x[id],depth+1);var eid=encodeURIComponent(id);if(x[eid])walk(x[eid],depth+1);var keys=['states','history','data','result','items','changes','state_changes','rows','values','events','entities'];for(var k=0;k<keys.length;k++)if(x[keys[k]])walk(x[keys[k]],depth+1);var vals=Object.values(x);for(var j=0;j<vals.length;j++)walk(vals[j],depth+1);}}
    walk(json,0);
    var pts=rows.map(function(r){return [shellHistoryTime(r),shellHistoryNumber(shellHistoryState(r))]}).filter(function(p){return Number.isFinite(p[0])&&Number.isFinite(p[1])}).sort(function(a,b){return a[0]-b[0]});var uniq=[],seenPts={};for(var u=0;u<pts.length;u++){var key=pts[u][0]+'|'+pts[u][1];if(!seenPts[key]){seenPts[key]=1;uniq.push(pts[u]);}}return uniq;
  }
  async function shellFetchHistoryPoints(entityId,startIso,endIso){
    var h=shellGetParentHassObject();
    if(!h||typeof h.callApi!=='function') return {points:[],source:'no_parent_hass'};
    var rawStart=startIso, encStart=encodeURIComponent(rawStart), rawEnd=endIso, encEnd=encodeURIComponent(rawEnd), encId=encodeURIComponent(entityId);
    var paths=[
      'history/period/'+encStart+'?filter_entity_id='+encId+'&end_time='+encEnd+'&minimal_response',
      'history/period/'+rawStart+'?filter_entity_id='+encId+'&end_time='+encEnd+'&minimal_response',
      'history/period/'+encStart+'?filter_entity_id='+encId+'&end_time='+encEnd,
      'history/period/'+encStart+'?filter_entity_id='+encId+'&end_time='+encEnd+'&minimal_response=0'
    ];
    for(var i=0;i<paths.length;i++){
      try{var json=await h.callApi('GET',paths[i]);var pts=shellParseHistoryRows(json,entityId);if(pts.length)return {points:pts,source:'parent_callapi_path_'+i};}catch(e){}
    }
    try{var json2=await h.callApi('GET','history/period/'+encStart,{filter_entity_id:entityId,end_time:rawEnd,minimal_response:true});var pts2=shellParseHistoryRows(json2,entityId);if(pts2.length)return {points:pts2,source:'parent_callapi_params'};}catch(e){}
    return {points:[],source:'parent_callapi_empty'};
  }
  async function shellHandleHistoryRequest(d,targetWin){
    var rid=d.requestId||('r'+(shellHistorySeq++));
    var entityId=String(d.entityId||'');
    var startIso=String(d.start||'');
    var endIso=String(d.end||'');
    var result={points:[],source:'bad_request'};
    try{
      if(entityId&&startIso&&endIso) result=await shellFetchHistoryPoints(entityId,startIso,endIso);
    }catch(e){
      result={points:[],source:'parent_exception_'+String(e&&e.message||e).slice(0,80)};
    }
    var payload={type:'smart-energy-history-response',requestId:rid,entityId:entityId,points:result.points||[],source:result.source||''};
    try{ if(targetWin&&targetWin.postMessage) targetWin.postMessage(payload,'*'); }catch(e){}
    try{ if(frame&&frame.contentWindow&&frame.contentWindow!==targetWin) frame.contentWindow.postMessage(payload,'*'); }catch(e){}
  }
  window.__smartEnergyFetchHistoryPoints=function(entityId,startIso,endIso){return shellFetchHistoryPoints(String(entityId||''),String(startIso||''),String(endIso||''));};
  window.__smartEnergyShellReady=true;

  async function exists(url){try{const r=await fetch(url+'?check=69_8_'+Date.now()+'&rnd='+Math.random().toString(16).slice(2),{cache:'no-store'});return r.ok;}catch(e){return false;}}
  function active(btn){buttons.forEach(b=>b.classList.remove('active'));btn.classList.add('active');}
  function postView(btn){
    const view=btn.dataset.view||'global';
    if(btn.dataset.module==='voltronic'){
      try{frame.contentWindow.postMessage({type:'smartEnergyShowVoltronicTab',view},'*');}catch(e){}
    }
  }
  function load(btn){
    active(btn);
    empty.style.display='none';
    frame.style.display='block';
    title.textContent=btn.dataset.title||btn.dataset.label;
    if(SV_BROADCASTING_MODE && btn.dataset.module==='jkbms') title.textContent='BMS1';
    const view=btn.dataset.view||'';
    const baseUrl=btn.dataset.url;
    const isBmsAlarmTarget=false && SV_BROADCASTING_MODE && btn.dataset.module==='jkbms';
    const targetBms=isBmsAlarmTarget ? shellResolveBmsAlarmIndex(1) : 0;
    let url=baseUrl;
    if(isBmsAlarmTarget){
      try{localStorage.setItem('smart_energy_open_jk_alarm',String(targetBms));}catch(e){}
      try{localStorage.setItem('smart_energy_open_jk_alarm_tab','alarms');}catch(e){}
      url=baseUrl+'?open_bms_alarm='+encodeURIComponent(targetBms)+'&openBmsAlarm='+encodeURIComponent(targetBms)+'&tab=alarms&view=alarms';
    }
    function postBmsAlarm(){
      if(!isBmsAlarmTarget) return;
      try{ if(frame&&frame.contentWindow) frame.contentWindow.postMessage({type:'smart_energy_open_bms_alarm',bms:targetBms,tab:'alarms',view:'alarms',broadcasting:true},'*'); }catch(e){}
      setTimeout(function(){try{ if(frame&&frame.contentWindow) frame.contentWindow.postMessage({type:'smart_energy_open_bms_alarm',bms:targetBms,tab:'alarms',view:'alarms',broadcasting:true},'*'); }catch(e){}},250);
      setTimeout(function(){try{ if(frame&&frame.contentWindow) frame.contentWindow.postMessage({type:'smart_energy_open_bms_alarm',bms:targetBms,tab:'alarms',view:'alarms',broadcasting:true},'*'); }catch(e){}},900);
    }
    if(currentUrl!==url){
      currentUrl=url;
      frame.onload=()=>{postView(btn);sendTokenToFrame();setTimeout(sendTokenToFrame,500);postBmsAlarm();};
      frame.src=url+(url.indexOf('?')>=0?'&':'?')+'v=69_8_'+Date.now()+'&rnd='+Math.random().toString(16).slice(2)+(view&&!isBmsAlarmTarget?'#'+view:'');
    }else{
      postView(btn);
      sendTokenToFrame();
      postBmsAlarm();
    }
  }

  function shellResolveBmsAlarmIndex(i){
    i=parseInt(i,10); if(!isFinite(i)||i<1) i=1;
    if(SV_BROADCASTING_MODE){
      var m=parseInt(SV_BMS_MASTER_INDEX,10);
      if(isFinite(m)&&m>0) return m;
    }
    return i;
  }
  function shellOpenBmsAlarm(i){
    i=shellResolveBmsAlarmIndex(i);
    const btn=buttons.find(b=>b.dataset.module==='jkbms');
    if(!btn) return;
    try{localStorage.setItem('smart_energy_open_jk_alarm',String(i));}catch(e){}
    try{localStorage.setItem('smart_energy_open_jk_alarm_tab','alarms');}catch(e){}
    try{localStorage.setItem('smart_energy_open_jk_alarm_label',SV_BROADCASTING_MODE?'BMS1':'BMS '+i);}catch(e){}
    if(SV_BROADCASTING_MODE){
      try{localStorage.setItem('smart_energy_open_jk_alarm_broadcasting','1');}catch(e){}
    }
    load(btn);
    const send=function(){
      try{
        if(frame&&frame.contentWindow){
          frame.contentWindow.postMessage({
            type:'smart_energy_open_bms_alarm',
            bms:i,
            tab:'alarms',
            label:SV_BROADCASTING_MODE?'BMS1':'BMS '+i,
            broadcasting:SV_BROADCASTING_MODE
          },'*');
        }
      }catch(e){}
    };
    setTimeout(send,150); setTimeout(send,500); setTimeout(send,1100);
  }

  async function init(){
    const okByModule={};
    for(const b of buttons){
      const mod=b.dataset.module;
      if(!(mod in okByModule)) okByModule[mod]=await exists(b.dataset.url);
    }
    const available=[];
    for(const b of buttons){
      if(okByModule[b.dataset.module]){available.push(b);}else{b.classList.add('missing');}
    }
    count.textContent=String(Object.values(okByModule).filter(Boolean).length);
    if(!available.length){frame.style.display='none';empty.style.display='flex';return;}
    available.forEach(b=>b.onclick=()=>load(b));
    const def=available.find(b=>b.dataset.module==='voltronic'&&b.dataset.view==='global')||available[0];
    load(def);
  }
  window.addEventListener('message',function(ev){var d=ev.data||{};if(d.type==='smart-energy-request-ha-token')sendTokenToFrame();if(d.type==='smart-energy-history-request')shellHandleHistoryRequest(d,ev.source);if(d.type==='smart_energy_open_bms_alarm'||d.type==='smart-energy-open-jk-alarm')shellOpenBmsAlarm(d.bms||d.i||d.index||1);});
  init();
  setTimeout(sendTokenToFrame,800);
  setInterval(sendTokenToFrame,5000);
})();
</script>
</body>
</html>`;
}

// =====================================================
// SHARED SHELL + VOLTRONIC MODULE FILE - FS DIRECT VERIFY
// =====================================================
// Ce nœud écrit directement les 2 fichiers HTML avec fs.writeFileSync.
// Il ne dépend plus des nodes file pour voltronic.html ni index.html.

const fs = global.get("fs");
const path = global.get("path");

if (!fs || !path) {
    node.error("fs/path non disponible dans functionGlobalContext", msg);
    return null;
}

const BASE_DIR = "/homeassistant/www/smart-modular-dashboard";
const INDEX_FILE = `${BASE_DIR}/index.html`;
const VOLTRONIC_FILE = `${BASE_DIR}/voltronic.html`;

// IMPORTANT : le HTML Voltronic est celui qui est déjà dans msg.payload à ce stade.
// On n'utilise pas msgVoltronic.payload pour éviter tout souci de copie d'objet.

function makeVoltronicEmbeddedModule(html) {
    html = String(html || "");

    // Le fichier Voltronic reste un HTML complet pour fonctionner seul,
    // mais son layout devient un module intégré quand il est chargé dans le shell commun.
    html = html.replace('<body>', '<body class="voltronic-module">');

    const embeddedCss = `
/* ===== VOLTRONIC EMBEDDED MODULE - NO LEFT SIDEBAR ===== */
body.voltronic-module{
  background:transparent!important;
  overflow:auto!important;
}
body.voltronic-module .app{
  min-height:100vh!important;
  padding:0!important;
  display:block!important;
  background:transparent!important;
}
body.voltronic-module .shell{
  display:block!important;
  grid-template-columns:1fr!important;
  min-height:auto!important;
}
body.voltronic-module .sidebar{
  display:none!important;
