      const headers=window.HA_TOKEN?{Authorization:'Bearer '+window.HA_TOKEN}:{};
      const r=await fetch(url,{headers,credentials:'include'});
      if(!r.ok)return [];
      const j=await r.json();
      const rows=(Array.isArray(j)&&Array.isArray(j[0]))?j[0]:[];
      return rows.map(row=>{
        const t=new Date(row.last_changed||row.last_updated||row[0]).getTime();
        const v=num(row.state??row[1]);
