    if(pts.length>460){const step=Math.ceil(pts.length/460); const last=pts[pts.length-1]; pts=pts.filter((_,i)=>i%step===0); if(pts[pts.length-1]!==last)pts.push(last)}
    const unit=(window.STATES?.[entityId]?.attributes?.unit_of_measurement)||'';
    const spec=axisSpec(entityId,unit,pts);
    const w=1120,h=470,padL=78,padR=32,padT=50,padB=74,plotW=w-padL-padR,plotH=h-padT-padB;
    const minT=Math.min(...pts.map(p=>p[0])), maxT=Math.max(...pts.map(p=>p[0]));
    const minV=spec.min, maxV=spec.max;
    const x=t=>padL+(t-minT)/(maxT-minT||1)*plotW;
    const y=v=>padT+plotH-(Math.max(minV,Math.min(maxV,v))-minV)/(maxV-minV||1)*plotH;
    const line=pts.map((p,i)=>(i?'L':'M')+x(p[0]).toFixed(1)+' '+y(p[1]).toFixed(1)).join(' ');
    let grid='';
    const ticks=[0,.25,.5,.75,1];
    ticks.forEach(r=>{
      const v=minV+(maxV-minV)*r, yy=y(v);
      grid+='<line x1="'+padL+'" y1="'+yy.toFixed(1)+'" x2="'+(w-padR)+'" y2="'+yy.toFixed(1)+'" stroke="rgba(126,161,206,.16)"/><text x="'+(padL-12)+'" y="'+(yy+5).toFixed(1)+'" fill="#b8c7dd" font-size="13" font-weight="900" text-anchor="end">'+(maxV<=1?v.toFixed(2):Math.round(v))+'</text>';
    });
    for(let i=0;i<=6;i++){
      const t=minT+(maxT-minT)*i/6, xx=x(t);
      const lab=new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
      grid+='<line x1="'+xx.toFixed(1)+'" y1="'+padT+'" x2="'+xx.toFixed(1)+'" y2="'+(padT+plotH)+'" stroke="rgba(126,161,206,.10)"/><text x="'+xx.toFixed(1)+'" y="'+(h-28)+'" fill="#b8c7dd" font-size="13" font-weight="900" text-anchor="middle">'+lab+'</text>';
    }
    const cur=pts[pts.length-1][1];
    body.innerHTML='<svg class="history-svg sv-history-clean" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><rect width="'+w+'" height="'+h+'" fill="#06101d"/>'+grid+'<path d="'+line+'" fill="none" stroke="rgba(46,199,255,.22)" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"></path><path d="'+line+'" fill="none" stroke="#2ec7ff" stroke-width="3.8" stroke-linecap="round" stroke-linejoin="round"></path><rect class="history-hit" x="'+padL+'" y="'+padT+'" width="'+plotW+'" height="'+plotH+'" fill="transparent"/><text x="'+(w-28)+'" y="37" fill="#edf5ff" font-size="26" font-weight="1000" text-anchor="end">'+cur.toFixed(2)+' '+unit+'</text><text x="'+padL+'" y="25" fill="#91a7c4" font-size="13" font-weight="900">'+spec.label+'</text></svg>';
    const hit=body.querySelector('.history-hit');
    if(hit){
      hit.addEventListener('mousemove',ev=>{
        const rect=hit.getBoundingClientRect();
        const ratio=Math.max(0,Math.min(1,(ev.clientX-rect.left)/(rect.width||1)));
        const target=minT+(maxT-minT)*ratio;
        let best=pts[0]; for(const p of pts){if(Math.abs(p[0]-target)<Math.abs(best[0]-target))best=p}
        const label=new Date(best[0]).toLocaleString([], {day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
        if(window.historyTooltip) window.historyTooltip(ev,label,best[1],unit);
      });
      hit.addEventListener('mouseleave',()=>window.hideHistoryTooltip&&window.hideHistoryTooltip());
    }
  }

  window.showMiniHistory=async function(entityId){
    if(String(entityId||'').includes('voltronic_global_pv_energy_today')) entityId='sensor.voltronic_global_pv_today';
    const modal=q('#history_modal'),title=q('#history_title'),sub=q('#history_sub'),body=q('#history_body');
