  }

  const style=document.createElement('style');
  style.textContent='#inverters .dynamic-note{display:none!important}.solar-total .ico{color:#ffc928!important;text-shadow:0 0 14px rgba(255,201,40,.55)!important}.n-grid .sv-grid-day-final{background:linear-gradient(135deg,rgba(6,182,212,.48),rgba(37,99,235,.24))!important;border-color:rgba(34,211,238,.95)!important}.n-grid .sv-grid-day-final small{color:#a5f3fc!important}';
  document.head.appendChild(style);

  const oldUpdate=window.update;
