(p[0])>=cut&&Number.isFinite(Number(p[1]))).slice(-1200);localStorage.setItem(key,JSON.stringify(arr));}catch(e){}}\nfunction localHistory(k,entity){try{const arr=JSON.parse(localStorage.getItem(historyStoreKey(k,entity||entityForKey(k)||k))||'[]');return Array.isArray(arr)?arr.map(p=>[Number(p[0]),Number(p[1])]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1])):[]}catch(e){return []}}\nfunction mergeHistory(a,b){const map=new Map();[...(a||[]),...(b||[])].forEach(p=>{if(Number.isFinite(Number(p[0]))&&Number.isFinite(Number(p[1])))map.set(Math.round(Number(p[0])/1000)*1000,[Number(p[0]),Number(p[1])]);});return Array.from(map.values()).sort((x,y)=>x[0]-y[0])}\nfunction isUsefulHistory(series){if(!Array.isArray(series)||series.length<6)return false;const span=series[series.length-1][0]-series[0][0];return span>30*60000}\nfunction downsampleSeries(series,maxPoints){\n  series=(series||[]).filter(x=>Number.isFinite(Number(x[0]))&&Number.isFinite(Number(x[1]))).sort((a,b)=>a[0]-b[0]);\n  if(series.length<=maxPoints)return series;\n  const out=[];\n  const bucket=Math.ceil(series.length/maxPoints);\n  for(let i=0;i<series.length;i+=bucket){\n    const chunk=series.slice(i,i+bucket);\n    const avgT=chunk.reduce((a,p)=>a+Number(p[0]),0)/chunk.length;\n    const avgV=chunk.reduce((a,p)=>a+Number(p[1]),0)/chunk.length;\n    out.push([avgT,avgV]);\n  }\n  return out;\n}\nfunction makeSmoothPath(pts){\n  if(!pts.length)return '';\n  if(pts.length===1)return 'M '+pts[0][0].toFixed(1)+' '+pts[0][1].toFixed(1);\n  let d='M '+pts[0][0].toFixed(1)+' '+pts[0][1].toFixed(1);\n  for(let i=0;i<pts.length-1;i++){\n    const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;\n    const cp1x=p1[0]+(p2[0]-p0[0])/6,cp1y=p1[1]+(p2[1]-p0[1])/6;\n    const cp2x=p2[0]-(p3[0]-p1[0])/6,cp2y=p2[1]-(p3[1]-p1[1])/6;\n    d+=' C '+cp1x.toFixed(1)+' '+cp1y.toFixed(1)+', '+cp2x.toFixed(1)+' '+cp2y.toFixed(1)+', '+p2[0].toFixed(1)+' '+p2[1].toFixed(1);\n  }\n  return d;\n}\nfunction drawHistory(k,series,entity){\n  const w=1120,h=470,pL=76,pR=30,pT=36,pB=62;\n  series=(series||[]).filter(x=>Number.isFinite(Number(x[0]))&&Number.isFinite(Number(x[1]))).sort((a,b)=>a[0]-b[0]);\n  if(series.length<2)series=fallbackSeries(k);\n  const rawSeries=series.slice();\n  const smoothSeries=downsampleSeries(series,360);\n  const vals=rawSeries.map(x=>Number(x[1])||0);\n  const t0=rawSeries[0][0],t1=rawSeries[rawSeries.length-1][0],tSpan=Math.max(1,t1-t0);\n  const rawMax=Math.max(...vals,1),sc=historyScale(k,entity,vals),min=sc.min,max=sc.max,span=Math.max(.001,max-min);\n  const plotW=w-pL-pR,plotH=h-pT-pB;\n  const pts=smoothSeries.map(x=>[pL+((x[0]-t0)/tSpan)*plotW,pT+(max-(Number(x[1])||0))/span*plotH,x]);\n  const path=makeSmoothPath(pts);\n  const areaPath=path?path+' L '+(w-pR).toFixed(1)+' '+(h-pB).toFixed(1)+' L '+pL+' '+(h-pB).toFixed(1)+' Z':'';\n  const yTicks=[0,.25,.5,.75,1].map(t=>max-(max-min)*t);\n  const xTicks=[0,.25,.5,.75,1].map(t=>pL+plotW*t);\n  const current=vals.length?vals[vals.length-1]:0;\n  document.getElementById('historyLive').textContent=historyFormat(k,current);\n  document.getElementById('historyTitle').textContent=friendlyName(entity,k);\n  document.getElementById('historyEntity').textContent=(entity||'courbe locale')+' · dernières 24h';\n  const base='Min '+historyFormat(k,min)+' · Max '+historyFormat(k,rawMax);\n  document.getElementById('historyChart').innerHTML='<svg id=\"historySvg\" viewBox=\"0 0 '+w+' '+h+'\" style=\"touch-action:none;pointer-events:auto\">'\n    +yTicks.map(v=>{const y=pT+(max-v)/span*plotH;return '<line class=\"historyGrid\" x1=\"'+pL+'\" y1=\"'+y.toFixed(1)+'\" x2=\"'+(w-pR)+'\" y2=\"'+y.toFixed(1)+'\"/><text class=\"historyLabel\" x=\"8\" y=\"'+(y+4).toFixed(1)+'\">'+historyFormat(k,v)+'</text>';}).join('')\n    +xTicks.map(x=>'<line class=\"historyGrid\" x1=\"'+x.toFixed(1)+'\" y1=\"'+pT+'\" x2=\"'+x.toFixed(1)+'\" y2=\"'+(h-pB)+'\"/>').join('')\n    +'<line class=\"historyAxis\" x1=\"'+pL+'\" y1=\"'+(h-pB)+'\" x2=\"'+(w-pR)+'\" y2=\"'+(h-pB)+'\"/>'\n    +'<line class=\"historyAxis\" x1=\"'+pL+'\" y1=\"'+pT+'\" x2=\"'+pL+'\" y2=\"'+(h-pB)+'\"/>'\n    +'<text class=\"historyLabel\" x=\"'+pL+'\" y=\"'+(h-20)+'\">'+new Date(t0).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})+'</text>'\n    +'<text class=\"historyLabel\" x=\"'+(w-pR-48)+'\" y=\"'+(h-20)+'\">'+new Date(t1).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})+'</text>'\n    +'<path class=\"historyArea\" d=\"'+areaPath+'\"/>'\n    +'<path class=\"historyLine\" d=\"'+path+'\"/>'\n    +'<line id=\"historyHoverLine\" class=\"historyHoverLine\" x1=\"0\" y1=\"'+pT+'\" x2=\"0\" y2=\"'+(h-pB)+'\" style=\"display:none;pointer-events:none\"/>'\n    +'<circle id=\"historyHoverDot\" class=\"historyHoverDot\" cx=\"0\" cy=\"0\" r=\"5\" style=\"display:none;pointer-events:none\"></circle>'\n    +'<g id=\"historyTip\" style=\"display:none;pointer-events:none\">'\n    +'<rect id=\"historyTipBg\" x=\"0\" y=\"0\" width=\"190\" height=\"68\" rx=\"10\" ry=\"10\" fill=\"rgba(5,18,31,.96)\" stroke=\"rgba(140,255,32,.75)\" stroke-width=\"1.2\"></rect>'\n    +'<text id=\"historyTipTime\" x=\"12\" y=\"22\" fill=\"#ffffff\" font-size=\"13\" font-weight=\"800\"></text>'\n    +'<text id=\"historyTipVal\" x=\"12\" y=\"46\" fill=\"#20caff\" font-size=\"20\" font-weight=\"950\"></text>'\n    +'<text id=\"historyTipSrc\" x=\"12\" y=\"61\" fill=\"#9db3ca\" font-size=\"10\" font-weight=\"700\">historique HA</text>'\n    +'</g>'\n    +'<rect id=\"historyHoverZone\" x=\"'+pL+'\" y=\"'+pT+'\" width=\"'+plotW+'\" height=\"'+plotH+'\" fill=\"rgba(0,0,0,0.001)\" style=\"cursor:crosshair;pointer-events:all\"></rect></svg>';\n  const meta=document.getElementById('historyMeta');\n  meta.textContent=base;\n  const svg=document.getElementById('historySvg'),\n        hoverLine=document.getElementById('historyHoverLine'),\n        hoverDot=document.getElementById('historyHoverDot'),\n        zone=document.getElementById('historyHoverZone'),\n        tip=document.getElementById('historyTip'),\n        tipTime=document.getElementById('historyTipTime'),\n        tipVal=document.getElementById('historyTipVal');\n  function pointAtClient(evt){\n    const rect=svg.getBoundingClientRect();\n    const relX=((evt.clientX-rect.left)/Math.max(1,rect.width))*w;\n    const ratio=Math.max(0,Math.min(1,(relX-pL)/plotW));\n    const targetT=t0+ratio*tSpan;\n    let lo=0,hi=rawSeries.length-1;\n    while(lo<hi){const mid=(lo+hi)>>1;if(rawSeries[mid][0]<targetT)lo=mid+1;else hi=mid;}\n    const a=rawSeries[Math.max(0,lo-1)],b=rawSeries[lo]||a;\n    const p=(Math.abs((a&&a[0]||0)-targetT)<Math.abs((b&&b[0]||0)-targetT))?a:b;\n    const px=pL+((p[0]-t0)/tSpan)*plotW;\n    const py=pT+(max-(Number(p[1])||0))/span*plotH;\n    return {p:p,px:px,py:Math.max(pT,Math.min(h-pB,py))};\n  }\n  function showPoint(evt){\n    if(!evt)return;\n    const r=pointAtClient(evt);\n    const value=Number(r.p[1])||0;\n    const d=new Date(r.p[0]);\n    const timeTxt=d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});\n    const valTxt=historyFormat(k,value);\n    hoverLine.setAttribute('x1',r.px.toFixed(1));hoverLine.setAttribute('x2',r.px.toFixed(1));hoverLine.style.display='block';\n    hoverDot.setAttribute('cx',r.px.toFixed(1));hoverDot.setAttribute('cy',r.py.toFixed(1));hoverDot.style.display='block';\n    tipTime.textContent=timeTxt;\n    tipVal.textContent=valTxt;\n    const tipW=190,tipH=68;\n    let tx=r.px+14,ty=r.py-tipH-14;\n    if(tx+tipW>w-pR)tx=r.px-tipW-14;\n    if(ty<pT)ty=r.py+14;\n    if(ty+tipH>h-pB)ty=h-pB-tipH-6;\n    tip.setAttribute('transform','translate('+tx.toFixed(1)+','+ty.toFixed(1)+')');\n    tip.style.display='block';\n    meta.textContent=timeTxt+' : '+valTxt+' · '+base;\n  }\n  function hidePoint(){\n    hoverLine.style.display='none';\n    hoverDot.style.display='none';\n    tip.style.display='none';\n    meta.textContent=base;\n  }\n  ['mousemove','pointermove','mousedown','click'].forEach(ev=>{\n    zone.addEventListener(ev,e=>{showPoint(e);});\n    svg.addEventListener(ev,e=>{showPoint(e);});\n  });\n  zone.addEventListener('touchstart',e=>{if(e.touches&&e.touches[0]){e.preventDefault();showPoint(e.touches[0]);}},{passive:false});\n  zone.addEventListener('touchmove',e=>{if(e.touches&&e.touches[0]){e.preventDefault();showPoint(e.touches[0]);}},{passive:false});\n  svg.addEventListener('touchstart',e=>{if(e.touches&&e.touches[0]){e.preventDefault();showPoint(e.touches[0]);}},{passive:false});\n  svg.addEventListener('touchmove',e=>{if(e.touches&&e.touches[0]){e.preventDefault();showPoint(e.touches[0]);}},{passive:false});\n  zone.addEventListener('mouseleave',hidePoint);\n}\n\nfunction parseHaHistory(data){\n  const arr=(Array.isArray(data)&&Array.isArray(data[0]))?data[0]:(Array.isArray(data)?data:[]);\n  return arr.map(s=>{\n    if(!s||typeof s!=='object')return [NaN,NaN];\n    const state=('state' in s)?s.state:(('s' in s)?s.s:s.value);\n    let ts=s.last_changed||s.last_updated||s.lc||s.lu||s.last_changed_ts||s.last_updated_ts;\n    if(typeof ts==='number')ts=ts<1000000000000?ts*1000:ts;\n    else ts=new Date(ts).getTime();\n    return [ts,Number(String(state).replace(',','.'))];\n  })\n    .filter(x=>Number.isFinite(x[0])&&Number.isFinite(x[1]))\n    .sort((a,b)=>a[0]-b[0]);\n}\nfunction getHaToken(){\n  try{\n    const raw=localStorage.getItem('hassTokens')||sessionStorage.getItem('hassTokens');\n    if(!raw)return '';\n    const t=JSON.parse(raw);\n    return t.access_token||'';\n  }catch(e){return ''}\n}\nasync function fetchHaHistory(entity){\n  if(!entity)return [];\n  const end=new Date();\n  const start=new Date(end.getTime()-24*3600000);\n  const h=hass();\n  try{\n    if(h&&h.callWS){\n      const data=await h.callWS({type:'history/history_during_period',start_time:start.toISOString(),end_time:end.toISOString(),entity_ids:[entity],minimal_response:false,no_