function firstWritableDir(candidates) {
  for (const dir of candidates) {
    try {
      fs.mkdirSync(dir, { recursive: true });
      fs.accessSync(dir, fs.constants.W_OK);
      return dir;
    } catch (_) {}
  }
  return candidates[0];
}

function buildHomeShellHtml() {
  // Dashboard House = même rendu/menu que Voltronic, mais dans un fichier séparé.
  // Important : voltronic.html reste intact. Les modules externes sont ajoutés uniquement ici.
  let house = html;

  house = house.replace(
    '<title>Smart Voltronic Premium House</title>',
    '<title>Smart Energy Premium House</title>'
  );

  house = house.replace(
    'body:before{content:"SMART_VOLTRONIC_PREMIUM_HOUSE_V104";display:none}',
    'body:before{content:"SMART_ENERGY_PREMIUM_HOUSE_V104_WITH_JK_MENU";display:none}'
  );

  // Ajout JK/Finance dans le menu Voltronic House uniquement.
  house = house.replace(
    '<button data-view="settings"><span class="ico">⚙</span>Réglages</button></nav>',
    '<button data-view="settings"><span class="ico">⚙</span>Réglages</button>' +
    '<button class="houseModuleBtn" data-view="jkbms" data-module-url="/local/smart-modular-dashboard/jkbms.html" style="display:none"><span class="ico">🔋</span>JK-BMS</button>' +
    '<button class="houseModuleBtn" data-view="finance" data-module-url="/local/smart-modular-dashboard/finance.html" style="display:none"><span class="ico">💶</span>Finance</button></nav>'
  );

  // Pages iframe internes au dashboard House, sans reprendre l'ancien shell/menu.
  house = house.replace(
    '    </section>\n  </main>',
    '    </section>\n' +
    '    <section class="pageView pageJkbms houseModulePage"><iframe id="houseJkbmsFrame" title="JK-BMS" src="about:blank"></iframe></section>\n' +
    '    <section class="pageView pageFinance houseModulePage"><iframe id="houseFinanceFrame" title="Finance" src="about:blank"></iframe></section>\n' +
    '  </main>'
  );

  // CSS pour les pages JK/Finance dans le même menu visuel que House.
  house = house.replace(
    '.main.view-inverters .pageInverters,.main.view-energy .pageEnergy{display:block}',
    '.main.view-inverters .pageInverters,.main.view-energy .pageEnergy,.main.view-jkbms .pageJkbms,.main.view-finance .pageFinance{display:block}'
  );
  house = house.replace(
    '</style>',
    '.houseModulePage{padding:0!important;background:#06111f!important}.houseModulePage iframe{width:100%;height:100%;border:0;background:#06111f;display:block}.houseModuleBtn{display:none}\n</style>'
  );

  // Le clic menu garde la logique Voltronic, mais ajoute JK/Finance dans ce même menu.
  const oldMenuHandler = "document.querySelectorAll('.menu button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.menu button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelector('.main').classList.remove('view-inverters','view-energy');if(btn.dataset.view==='inverters')document.querySelector('.main').classList.add('view-inverters');if(btn.dataset.view==='energy')document.querySelector('.main').classList.add('view-energy');if(btn.dataset.view==='settings')openSettings()}));";
  const newMenuHandler = "function openHouseModule(view,url){const main=document.querySelector('.main');main.classList.add('view-'+view);const id=view==='jkbms'?'houseJkbmsFrame':'houseFinanceFrame';const frame=document.getElementById(id);if(frame&&frame.dataset.loaded!=='1'){frame.dataset.loaded='1';frame.src=url+'?embed=1&v='+Date.now();}}\n" +
    "document.querySelectorAll('.menu button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.menu button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const main=document.querySelector('.main');main.classList.remove('view-inverters','view-energy','view-jkbms','view-finance');if(btn.dataset.view==='inverters')main.classList.add('view-inverters');if(btn.dataset.view==='energy')main.classList.add('view-energy');if(btn.dataset.view==='settings')openSettings();if(btn.dataset.view==='jkbms')openHouseModule('jkbms',btn.dataset.moduleUrl);if(btn.dataset.view==='finance')openHouseModule('finance',btn.dataset.moduleUrl);}));\n" +
    "async function detectHouseModules(){const checks=[...document.querySelectorAll('.houseModuleBtn')];for(const btn of checks){try{const r=await fetch(btn.dataset.moduleUrl+'?check='+Date.now(),{cache:'no-store'});btn.style.display=r.ok?'grid':'none';}catch(e){btn.style.display='none';}}}\n" +
    "detectHouseModules();";
  house = house.replace(oldMenuHandler, newMenuHandler);

  return house;
}

try {
  const moduleBaseDir = firstWritableDir(["/homeassistant/www/smart-modular-dashboard", "/config/www/smart-modular-dashboard"]);
  const houseBaseDir = firstWritableDir(["/homeassistant/www/smart-modular-dashboard-house", "/config/www/smart-modular-dashboard-house"]);

  // Le module Voltronic reste dans son fichier standard : il n'est pas transformé en shell House.
  fs.writeFileSync(moduleBaseDir + "/voltronic.html", html, "utf8");

  // Le dashboard House est un shell séparé, qui ajoute JK/Finance au menu uniquement si leurs fichiers existent.
  fs.writeFileSync(houseBaseDir + "/index.html", buildHomeShellHtml(), "utf8");

  node.status({ fill: "green", shape: "dot", text: "House séparé + Voltronic intact" });
} catch (e) {
  node.error("Erreur écriture HTML House premium : " + e.message, msg);
  return null;
}
msg.topic = "build-house-iframe";
msg.payload = "";
return msg;

const inputEnv = msg.payload.toString().trim();

let configPath;
let statusColor;
let bip;

switch(inputEnv) {
    case 'HAOS':
        configPath = '/data/options.json';
        msg.environment = 'Home Assistant OS';
        bip = 1;
        statusColor = 'green';
        break;
    case 'Docker':
        configPath = '/data/options.json';
        msg.environment = 'Docker (autre)';
        bip = 2;
        statusColor = 'blue';
        break;
    case 'Linux':
        configPath = '/data/options.json';
        msg.environment = 'Linux barebone';
        bip = 3;
        statusColor = 'yellow';
        break;
    case 'Windows':
        configPath = 'C:\\data\\options.json';
        msg.environment = 'Windows';
        bip = 4;
        statusColor = 'purple';
        break;
    default:
        configPath = './data/options.json';
        msg.environment = 'Inconnu';
        bip = 5;
        statusColor = 'red';
}

// 2ème digit : premium actif ou non
const premium = global.get('premium') || {};
const premiumDigit = (premium.status === 'active') ? '1' : '0';

msg.filename = configPath;
msg.payload = { "bip": String(bip) + premiumDigit };  // ex: "11", "10", "21"...
msg.headers = { "Content-Type": "application/json" };
node.status({fill: statusColor, shape: "dot", text: msg.environment});
return msg;
